//! The conformance vectors (roadmap 00, phase 0): signed bundles, each with the verdict every
//! consumer must reach, so mediatore, mediatore-guest and the gateway test against the same files
//! notaio does.
//!
//! The vectors are generated by `make conformance` (the `conformance` example) with a fixed,
//! published, test-only key and fixed clocks, so they are byte for byte reproducible, and
//! `make conformance-check` fails CI when the checked-in files drift. A consumer reads
//! [`VECTORS_JSON`] through its git dependency, verifies each vector its own way, and compares with
//! [`Vector::expect`]; [`run`] does exactly that with this crate's [`accept`].
//!
//! The key is for these vectors only. Never trust it anywhere else.

use base64::{engine::general_purpose::STANDARD, Engine as _};
use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};

use crate::floor::{accept, FloorEntry, MemoryFloor, VersionFloor};
use crate::{BundleError, Envelope, TrustedKeys};

/// The vectors, as generated: the [`Suite`] in JSON.
pub const VECTORS_JSON: &str = include_str!("../conformance/vectors.json");

/// The JSON Schema of the bundle payload these vectors are signed over.
pub const PAYLOAD_SCHEMA_JSON: &str = include_str!("../conformance/bundle-v3.schema.json");

/// Every vector, with what a consumer needs to check it.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Suite {
    /// What this file is: `sandbox.firestoned.io/conformance/v1`.
    pub schema: String,
    /// The bundle schema the vectors exercise.
    pub bundle_schema: String,
    /// The keys a consumer trusts for these vectors: key id and standard base64 public key.
    pub trusted_keys: Vec<TrustedKey>,
    /// The policy every vector is about, where its floor is kept.
    pub policy: PolicyCoordinates,
    pub vectors: Vec<Vector>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct TrustedKey {
    pub key_id: String,
    pub public_key: String,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct PolicyCoordinates {
    pub namespace: String,
    pub name: String,
}

/// One case: an envelope, the consumer's clock and floor before it, and the verdict.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Vector {
    pub name: String,
    pub description: String,
    /// The consumer's clock.
    pub now: DateTime<Utc>,
    /// The floor the consumer holds for the policy before this envelope; None for first sight.
    pub floor: Option<FloorEntry>,
    pub envelope: Envelope,
    pub expect: Expect,
}

/// The verdict a consumer must reach.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "outcome", rename_all = "camelCase")]
pub enum Expect {
    /// Accepted, at this version, leaving this floor.
    #[serde(rename_all = "camelCase")]
    Accepted {
        version: u64,
        floor_after: FloorEntry,
    },
    /// Refused, for this reason: a [`BundleError`] variant name, see [`error_name`].
    Refused { error: String },
}

/// The suite in [`VECTORS_JSON`].
///
/// # Errors
/// Only if the checked-in file does not parse, which `make conformance-check` rules out.
pub fn suite() -> Result<Suite, serde_json::Error> {
    serde_json::from_str(VECTORS_JSON)
}

impl Suite {
    /// The suite's trusted keys, ready for [`crate::verify_bundle`].
    ///
    /// # Errors
    /// `BundleError::Key` for a key that is not 32 bytes of standard base64.
    pub fn keys(&self) -> Result<TrustedKeys, BundleError> {
        let mut keys = TrustedKeys::new();
        for k in &self.trusted_keys {
            let raw = STANDARD
                .decode(&k.public_key)
                .map_err(|e| BundleError::Key(e.to_string()))?;
            let public: [u8; 32] = raw
                .try_into()
                .map_err(|_| BundleError::Key("a public key is 32 bytes".into()))?;
            keys.insert(&k.key_id, public)?;
        }
        Ok(keys)
    }
}

/// The stable name of a refusal, as the vectors spell it: the [`BundleError`] variant.
pub fn error_name(e: &BundleError) -> &'static str {
    match e {
        BundleError::PayloadType(_) => "PayloadType",
        BundleError::NoValidSignature => "NoValidSignature",
        BundleError::Malformed(_) => "Malformed",
        BundleError::Schema(_) => "Schema",
        BundleError::DigestMismatch => "DigestMismatch",
        BundleError::Expired(_) => "Expired",
        BundleError::NotYetValid(_) => "NotYetValid",
        BundleError::Downgrade { .. } => "Downgrade",
        BundleError::Signing(_) => "Signing",
        BundleError::Key(_) => "Key",
        BundleError::NonCanonical(_) => "NonCanonical",
        BundleError::StaleIncarnation { .. } => "StaleIncarnation",
        BundleError::Floor(_) => "Floor",
    }
}

/// Checks `vector` with this crate's [`accept`] and a fresh in-memory floor: what any consumer's
/// verifier must reproduce.
///
/// # Errors
/// A description of how the outcome differs from [`Vector::expect`].
pub fn run(suite: &Suite, vector: &Vector, keys: &TrustedKeys) -> Result<(), String> {
    let mut floor = MemoryFloor::default();
    let (ns, name) = (&suite.policy.namespace, &suite.policy.name);
    if let Some(held) = &vector.floor {
        floor
            .set(ns, name, held.clone())
            .map_err(|e| e.to_string())?;
    }
    let outcome = accept(&vector.envelope, keys, vector.now, &mut floor);
    match (&vector.expect, outcome) {
        (
            Expect::Accepted {
                version,
                floor_after,
            },
            Ok(payload),
        ) => {
            if payload.meta.version != *version {
                return Err(format!(
                    "accepted version {}, expected {version}",
                    payload.meta.version
                ));
            }
            let after = floor.get(ns, name);
            if after.as_ref() != Some(floor_after) {
                return Err(format!(
                    "floor after is {after:?}, expected {floor_after:?}"
                ));
            }
            Ok(())
        }
        (Expect::Refused { error }, Err(e)) if error_name(&e) == error => {
            // A refused bundle never moves the floor.
            if floor.get(ns, name) != vector.floor {
                return Err("a refused bundle moved the floor".into());
            }
            Ok(())
        }
        (expect, got) => Err(format!(
            "expected {expect:?}, got {:?}",
            got.map(|p| p.meta.version).map_err(|e| error_name(&e))
        )),
    }
}
